package org.senda.browser.core

import android.content.Context
import android.content.res.Resources
import android.os.Build
import android.os.LocaleList
import androidx.compose.runtime.compositionLocalOf
import java.util.Locale

/**
 * Representa una opción de idioma seleccionable por el usuario.
 */
data class LanguageOption(
    val code: String,
    val displayName: String,
    val nativeName: String
)

/**
 * Gestor de localización y locales para Senda.
 * Soporta cambio dinámico de idioma en la UI y sincronización con el sistema Android.
 */
object SendaLocaleManager {

    val initialSystemLocale: Locale = try {
        val list = Resources.getSystem().configuration.locales
        if (!list.isEmpty && list[0] != null) list[0] else Locale.getDefault()
    } catch (_: Exception) {
        Locale.getDefault()
    }

    val supportedLanguages = listOf(
        LanguageOption("SYSTEM", "Predeterminado del sistema / System Default", "Sistema"),
        LanguageOption("DE", "Deutsch", "Deutsch"),
        LanguageOption("EN", "English", "English"),
        LanguageOption("ES", "Español", "Español"),
        LanguageOption("FR", "Français", "Français"),
        LanguageOption("PT", "Português", "Português"),
        LanguageOption("IT", "Italiano", "Italiano"),
        LanguageOption("JA", "日本語 (Japanese)", "日本語"),
        LanguageOption("ZH", "中文 (Chinese)", "中文")
    )

    private fun getSystemPropertyLocale(): Locale? {
        return try {
            val getMethod = Class.forName("android.os.SystemProperties").getMethod("get", String::class.java, String::class.java)
            val tag = (getMethod.invoke(null, "persist.sys.locale", "") as? String)?.takeIf { it.isNotBlank() }
                ?: (getMethod.invoke(null, "ro.product.locale", "") as? String)?.takeIf { it.isNotBlank() }
            if (!tag.isNullOrBlank()) {
                Locale.forLanguageTag(tag.replace("_", "-"))
            } else null
        } catch (_: Exception) {
            null
        }
    }

    fun getSystemLocale(context: Context? = null): Locale {
        getSystemPropertyLocale()?.let { return it }

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.UPSIDE_DOWN_CAKE && context != null) {
            try {
                val lm = context.getSystemService(android.app.LocaleManager::class.java)
                val sysLocales = lm?.systemLocales
                if (sysLocales != null && !sysLocales.isEmpty) {
                    val first = sysLocales[0]
                    if (first != null) return first
                }
            } catch (_: Exception) {}
        }

        try {
            val locales = Resources.getSystem().configuration.locales
            if (!locales.isEmpty) {
                val first = locales[0]
                if (first != null) return first
            }
        } catch (_: Exception) {}

        return initialSystemLocale
    }

    fun getEffectiveLanguage(savedLang: String, context: Context? = null): String {
        if (savedLang.equals("SYSTEM", ignoreCase = true)) {
            val systemLocale = getSystemLocale(context)
            val lang = systemLocale.language.lowercase()
            return when {
                lang.startsWith("de") -> "DE"
                lang.startsWith("es") -> "ES"
                lang.startsWith("fr") -> "FR"
                lang.startsWith("pt") -> "PT"
                lang.startsWith("it") -> "IT"
                lang.startsWith("ja") -> "JA"
                lang.startsWith("zh") -> "ZH"
                else -> "EN"
            }
        }
        return savedLang.uppercase()
    }

    fun getSystemLanguageLabel(context: Context? = null): String {
        return try {
            val systemLocale = getSystemLocale(context)
            val name = systemLocale.getDisplayLanguage(systemLocale).replaceFirstChar { it.uppercase() }
            if (name.isNotBlank()) name else "System"
        } catch (_: Exception) {
            "System"
        }
    }

    fun applyLocale(context: Context, savedLang: String) {
        val targetLocale = if (savedLang.equals("SYSTEM", ignoreCase = true)) {
            getSystemLocale(context)
        } else {
            Locale.forLanguageTag(savedLang.lowercase())
        }

        Locale.setDefault(targetLocale)

        try {
            val config = context.resources.configuration
            config.setLocale(targetLocale)
            config.setLayoutDirection(targetLocale)
            @Suppress("DEPRECATION")
            context.resources.updateConfiguration(config, context.resources.displayMetrics)
        } catch (_: Exception) {}

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            try {
                val localeManager = context.getSystemService(android.app.LocaleManager::class.java)
                val localeList = if (savedLang.equals("SYSTEM", ignoreCase = true)) {
                    LocaleList.getEmptyLocaleList()
                } else {
                    LocaleList.forLanguageTags(savedLang.lowercase())
                }
                localeManager?.applicationLocales = localeList
            } catch (_: Exception) {}
        }
    }
}

