    override val dlg_about_third_party = "Senda integriert erstklassige Open-Source-Komponenten:\n\n• GeckoView (Mozilla Public License 2.0)\n• Jetpack Compose & AndroidX (Apache License 2.0)\n• Kotlin & Coroutines (Apache License 2.0)\n• HiddenApiBypass (Apache License 2.0)\n• uBlock Origin (GNU GPL v3)\n• Tor, tor-android, jtorctl (BSD 3-Clause)\n• llama.cpp / ggml (MIT)\n• Freie Kunst-Hintergründe (GPLv3 / CC0 Public Domain)"
    override val dlg_privacy_principles = "Senda Datenschutz-Grundsätze:\n\n1. Ihre Aufmerksamkeit gehört Ihnen: Keine invasiven Inhalte, manipulative Werbung oder Bindungsalgorithmen.\n\n2. Ihr Gerät gehört Ihnen: Null stille Telemetrie und keine verdeckte Datenerfassung.\n\n3. Offenes & freies Web: Volle Unterstützung für Open-Source-Software und ein dezentrales Netz."
    override val dlg_reader_mode_desc = "Verwandelt jeden Webartikel in eine saubere Leseansicht, frei von Werbung, Trackern und Ablenkungen."
    override val dlg_ai_title = "Assistent & Lokale KI"
    override val dlg_ai_desc = "In Senda respektieren Lese- und Assistenzfunktionen Ihre Privatsphäre:\n\n• Keine versteckte Telemetrie.\n• Kein Hochladen privater Daten in kommerzielle Clouds.\n• Lokale und private Verarbeitung auf dem Gerät."
    override val dlg_translations_title = "Seitenübersetzung"
    override val dlg_translations_desc = "Die integrierte Seitenübersetzung ist in Senda noch nicht verfügbar. Sie wird auf deinem Gerät laufen, ohne Text an Dritte zu senden."
