    override val dlg_zero_telemetry_title = "Declaración de Privacidad Senda:"
    override val dlg_zero_telemetry_content = "1. Cero Telemetría: Senda no envía ningún paquete de datos analíticos ni métricas sobre tus hábitos.\n\n2. Cero Estudios Remotos: No se inyectan experimentos ni análisis A/B en tu navegador.\n\n3. Cero Identificadores de Dispositivo: No se genera ningún ID único para tu teléfono.\n\n4. Control Local: Tus marcadores, contraseñas e historial solo existen en tu dispositivo."
    override val dlg_about_content = "Navegador web ligero, rápido y privado con motor GeckoView de Mozilla. Diseñado para ofrecer navegación fluida, seguridad robusta y respeto total a tu privacidad."
    override val dlg_about_senda_build = "Senda Browser\nVersión 0.1.0-alpha (Build 1)"
    override val dlg_about_license_details = "Licencia: GNU General Public License v3 (GPLv3)\nArquitectura: GeckoView GeckoRuntime Nativo\nPlataforma: Android (64-bit)"
    override val dlg_about_third_party = "Senda integra componentes de software libre de clase mundial:\n\n• GeckoView (Mozilla Public License 2.0)\n• Jetpack Compose & AndroidX (Apache License 2.0)\n• Kotlin & Coroutines (Apache License 2.0)\n• HiddenApiBypass (Apache License 2.0)\n• uBlock Origin (GNU GPL v3)\n• Tor, tor-android, jtorctl (BSD 3-Clause)\n• llama.cpp / ggml (MIT)\n• Fondos Artísticos Libres (GPLv3 / CC0 Public Domain)"
    override val dlg_privacy_principles = "Principios de Privacidad de Senda:\n\n1. Tu atención te pertenece: Sin contenido invasivo, anuncios manipuladores ni algoritmos de retención corporativos.\n\n2. Tu dispositivo es tuyo: Cero telemetría silenciosa y cero recolección encubierta de tus datos de navegación.\n\n3. Web Abierta y Libre: Apoyo al software de código abierto y a una web descentralizada e independiente."
    override val dlg_reader_mode_desc = "Transforma cualquier artículo web en una lectura limpia, eliminando anuncios, rastreadores, banners y elementos distractores."
    override val dlg_ai_title = "Asistente e IA local"
    override val dlg_ai_desc = "En Senda, las funciones de asistencia y lectura respetan tu privacidad:\n\n• Sin telemetría oculta.\n• Sin subida de contenidos privados a nubes comerciales ni entrenamiento no consentido.\n• Procesamiento local y privado cuando sea técnicamente posible."
    override val dlg_translations_title = "Traducción de páginas"
