    override val dlg_privacy_principles = "Principes de Confidentialité de Senda :\n\n1. Votre attention vous appartient : Pas de publicités manipulatrices ni d'algorithmes de rétention.\n\n2. Votre appareil est à vous : Zéro télémétrie silencieuse et zéro collecte de données dissimulée.\n\n3. Web Ouvert et Libre : Soutien aux logiciels libres et à un web décentralisé."
