    override val dlg_zero_telemetry_title = "Dichiarazione sulla Privacy Senda:"
    override val dlg_zero_telemetry_content = "1. Zero Telemetria: Senda non invia alcun pacchetto di dati analitici né metriche di utilizzo.\n\n2. Nessuno Studio Remoto: Nessun esperimento A/B viene iniettato nel browser.\n\n3. Nessun Identificatore del Dispositivo: Non viene generato alcun ID univoco per il telefono.\n\n4. Controllo Locale: I tuoi segnalibri, password e cronologia risiedono esclusivamente sul tuo dispositivo."
    override val dlg_about_content = "Browser web leggero, veloce e privato con motore Mozilla GeckoView. Progettato per offrire navigazione fluida, sicurezza solida e totale rispetto per la tua privacy."
    override val dlg_about_senda_build = "Senda Browser\nVersione 0.1.0-alpha (Build 1)"
    override val dlg_about_license_details = "Licenza: GNU General Public License v3 (GPLv3)\nArchitettura: GeckoView GeckoRuntime Nativo\nPiattaforma: Android (64-bit)"
    override val dlg_about_third_party = "Senda integra componenti open source di prim'ordine:\n\n• GeckoView (Mozilla Public License 2.0)\n• Jetpack Compose & AndroidX (Apache License 2.0)\n• Kotlin & Coroutines (Apache License 2.0)\n• HiddenApiBypass (Apache License 2.0)\n• uBlock Origin (GNU GPL v3)\n• Tor, tor-android, jtorctl (BSD 3-Clause)\n• llama.cpp / ggml (MIT)\n• Sfondi Artistici Liberi (GPLv3 / CC0 Public Domain)"
    override val dlg_privacy_principles = "Principi di Privacy di Senda:\n\n1. La tua attenzione ti appartiene: Nessun contenuto invasivo, annunci manipolatori o algoritmi di ritenzione.\n\n2. Il tuo dispositivo è tuo: Zero telemetria nascosta e zero raccolta dati occulta.\n\n3. Web Aperto e Libero: Pieno supporto al software open source e a un web decentralizzato e indipendente."
    override val dlg_reader_mode_desc = "Trasforma qualsiasi articolo web in una lettura pulita, rimuovendo annunci, tracker e distrazioni."
    override val dlg_ai_title = "Assistente & IA Locale"
    override val dlg_ai_desc = "In Senda, le funzioni di assistenza rispettano la tua privacy:\n\n• Nessuna telemetria nascosta.\n• Nessun caricamento di dati privati su cloud commerciali.\n• Elaborazione locale e privata sul dispositivo."
    override val dlg_translations_title = "Traduzione delle pagine"
