    override val dlg_zero_telemetry_title = "Senda プライバシー宣言:"
    override val dlg_zero_telemetry_content = "1. テレメトリゼロ: Senda はいかなる分析データや利用統計も外部送信しません。\n\n2. 遠隔実験ゼロ: ブラウザにいかなる A/B テストや遠隔介入コードも挿入しません。\n\n3. 端末識別子ゼロ: スマートフォン固有の追跡 ID は一切生成しません。\n\n4. ローカル完全管理: ブックマーク、パスワード、閲覧履歴はあなたの端末内だけに保存されます。"
    override val dlg_about_content = "Mozilla GeckoView を搭載した高速で軽量、プライベートなウェブブラウザ。シームレスな操作感、強固なセキュリティ、妥協のないプライバシー保護を提供します。"
    override val dlg_about_senda_build = "Senda Browser\nバージョン 0.1.0-alpha (ビルド 1)"
    override val dlg_about_license_details = "ライセンス: GNU General Public License v3 (GPLv3)\nアーキテクチャ: GeckoView GeckoRuntime Native\nプラットフォーム: Android (64-bit)"
    override val dlg_about_third_party = "Senda は世界水準の自由・オープンソースコンポーネントを統合しています:\n\n• GeckoView (Mozilla Public License 2.0)\n• Jetpack Compose & AndroidX (Apache License 2.0)\n• Kotlin & Coroutines (Apache License 2.0)\n• HiddenApiBypass (Apache License 2.0)\n• uBlock Origin (GNU GPL v3)\n• Tor, tor-android, jtorctl (BSD 3-Clause)\n• llama.cpp / ggml (MIT)\n• Free Art Wallpapers (GPLv3 / CC0 Public Domain)"
    override val dlg_privacy_principles = "Senda プライバシー原則:\n\n1. あなたの注意はあなたのもの: 侵入的なコンテンツ、操作的な広告、ユーザー滞留アルゴリズムはありません。\n\n2. あなたの端末はあなたのもの: サイレントな遠隔測定や隠れたデータ収集は一切行いません。\n\n3. オープンで自由な Web: オープンソースソフトウェアと分散型で自立したウェブを支援します。"
    override val dlg_reader_mode_desc = "あらゆる記事を広告、トラッカー、バナーのないすっきりとした読書ビューに変換します。"
    override val dlg_ai_title = "プライベートなローカルアシスタント"
    override val dlg_ai_desc = "Senda では、リーダー機能とアシスタント機能がプライバシーを最優先します:\n\n• 隠されたテレメトリはありません。\n• 商業クラウドへの個人データアップロードや無断モデル学習は一切行いません。\n• 可能な限りすべての処理を端末内でローカルに実行します。"
    override val dlg_translations_title = "ウェブページの翻訳"
    override val dlg_translations_desc = "Senda のページ翻訳機能はまだ利用できません。今後、テキストを第三者に送らず端末上で動作する予定です。"
