    override val dlg_zero_telemetry_content = "1. 零遥测记录：Senda 坚决不上传任何使用分析数据或用户行为统计。\n\n2. 零远程实验：绝不在您的浏览器中强行注入任何远程 A/B 测试或实验代码。\n\n3. 零设备标识：绝不针对您的手机生成任何全局唯一的广告或设备追踪标识符。\n\n4. 本地全权掌控：您的个人书签、加密密码与浏览历史仅保存在您的个人设备中。"
    override val dlg_about_content = "基于 Mozilla GeckoView 原生引擎打造的轻量、高速且高度注重隐私保护的网络浏览器。致力于为您提供无缝流畅的浏览体验与极致的数字安全保障。"
    override val dlg_about_senda_build = "Senda 浏览器\n版本 0.1.0-alpha (Build 1)"
    override val dlg_about_license_details = "软件许可证: GNU General Public License v3 (GPLv3)\n核心架构: GeckoView GeckoRuntime Native\n运行平台: Android (64-bit)"
    override val dlg_about_third_party = "Senda 深度集成了世界一流的自由与开源软件组件：\n\n• GeckoView (Mozilla Public License 2.0)\n• Jetpack Compose & AndroidX (Apache License 2.0)\n• Kotlin & Coroutines (Apache License 2.0)\n• HiddenApiBypass (Apache License 2.0)\n• uBlock Origin (GNU GPL v3)\n• Tor, tor-android, jtorctl (BSD 3-Clause)\n• llama.cpp / ggml (MIT)\n• 自由艺术壁纸 (GPLv3 / CC0 Public Domain)"
    override val dlg_privacy_principles = "Senda 隐私核心原则：\n\n1. 您的注意力属于您自己：绝无侵入式内容、操纵性广告或旨在绑架注意力的算法。\n\n2. 您的设备由您全权做主：绝无隐蔽数据遥测，绝无后台暗中采集。\n\n3. 开放自由的网络世界：坚定拥护开源自由软件与去中心化独立互联网生态。"
    override val dlg_reader_mode_desc = "将网页文章一键排版为纯净阅读视界，自动过滤所有广告横幅与跟踪元素。"
    override val dlg_ai_title = "私有端侧离线智能助手"
    override val dlg_ai_desc = "在 Senda 中，阅读优化与智能辅助功能始终坚定捍卫您的隐私：\n\n• 绝无任何隐藏遥测。\n• 绝不向商业云服务上传私密数据，不参与任何未授权的模型训练。\n• 在技术可行的情况下全部采用端侧离线本地处理。"
